properties.query:
// Detects the use of wbadmin to dump sensitve files
// wbadmin is a legitimate tool but can be abused by attackers 
let cmd_all = dynamic(["start","backup"]);
let cmd_any = dynamic(["\\config\\SAM","\\config\\SECURITY","\\config\\SYSTEM","\\Windows\\NTDS\\NTDS.dit"]);
_Im_ProcessCreate(commandline_has_all=cmd_all,commandline_has_any=cmd_any,targetprocess_has_any="wbadmin.exe")
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
